<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\LegalPartner;
use App\Models\Plan;
use App\Services\LegalPartnerService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
class LegalPartnerAdminController extends Controller {
 public function invitations(){return DB::table('legal_partner_invitations')->orderByDesc('id')->limit(200)->get(['id','email','office_name','expires_at','used_at','revoked_at','delivery_status','created_at']);}
 public function invite(Request $r,LegalPartnerService $s){
  $d=$r->validate(['email'=>['required','email','max:255'],'office_name'=>['required','string','max:180'],'expires_in_days'=>['required','integer','min:1','max:30']]);$d['email']=mb_strtolower(trim($d['email']));
  abort_if(LegalPartner::where('email',$d['email'])->exists(),422,'Este e-mail já possui cadastro jurídico. Gerencie o escritório existente.');
  abort_if(DB::table('legal_partner_invitations')->where('email',$d['email'])->whereNull('used_at')->whereNull('revoked_at')->where('expires_at','>',now())->exists(),422,'Já existe um convite válido para este e-mail. Reemita ou revogue o convite existente.');
  return $this->issue($r,$s,$d);
 }
 private function issue(Request $r,LegalPartnerService $s,array $d,?int $existing=null){
  $token=Str::random(64);$expires=now()->addDays($d['expires_in_days']);
  $id=DB::transaction(function()use($r,$s,$d,$token,$expires,$existing){
   $values=['email'=>$d['email'],'office_name'=>$d['office_name'],'token_hash'=>hash('sha256',$token),'created_by'=>$r->user()->id,'expires_at'=>$expires,'delivery_status'=>'pending','updated_at'=>now()];
   if($existing){$row=DB::table('legal_partner_invitations')->where('id',$existing)->lockForUpdate()->first();abort_unless($row && !$row->used_at && !$row->revoked_at,422,'Convite já utilizado ou revogado.');DB::table('legal_partner_invitations')->where('id',$existing)->update($values);$id=$existing;}else{$id=DB::table('legal_partner_invitations')->insertGetId([...$values,'created_at'=>now()]);}
   $s->audit($r,'legal.invitation_issued',null,null,['invitation_id'=>$id,'reason'=>$d['reason']??null]);return $id;
  });
  $url='https://app.nofiodobigode.app.br/parceiro-juridico/?convite='.$token;
  $sent=$s->email($d['email'],'Convite para a Rede Jurídica · Fio do Bigode',"<p>Seu escritório foi convidado para se cadastrar na Rede Jurídica.</p><p><a href='{$url}'>Preencher cadastro do escritório</a></p><p>O convite é individual e expira em {$expires->format('d/m/Y')}. O acesso depende de análise e liberação administrativa.</p>");
  DB::table('legal_partner_invitations')->where('id',$id)->update(['delivery_status'=>$sent?'sent':'failed']);
  return response()->json(['id'=>$id,'invite_url'=>$url,'expires_at'=>$expires->toIso8601String(),'delivery_status'=>$sent?'sent':'failed','message'=>$sent?'Convite enviado por e-mail.':'Convite criado, mas o e-mail não foi enviado. Copie o link ou reemita o convite.'],201)->header('Cache-Control','no-store');
 }
 public function resend(Request $r,int $invitation,LegalPartnerService $s){$d=$r->validate(['reason'=>['required','string','min:5','max:500']]);$row=DB::table('legal_partner_invitations')->find($invitation);abort_unless($row,404);return $this->issue($r,$s,['email'=>$row->email,'office_name'=>$row->office_name,'expires_in_days'=>7,'reason'=>$d['reason']],$invitation);}
 public function revoke(Request $r,int $invitation,LegalPartnerService $s){$d=$r->validate(['reason'=>['required','string','min:5','max:500']]);DB::transaction(function()use($r,$invitation,$s,$d){$row=DB::table('legal_partner_invitations')->where('id',$invitation)->lockForUpdate()->first();abort_unless($row && !$row->used_at,422,'Convite não encontrado ou já utilizado.');DB::table('legal_partner_invitations')->where('id',$invitation)->update(['revoked_at'=>now(),'updated_at'=>now()]);$s->audit($r,'legal.invitation_revoked',null,null,['invitation_id'=>$invitation,'reason'=>$d['reason']]);});return response()->json(['message'=>'Convite revogado.']);}
 public function validateInvite(string $token){abort_unless(strlen($token)===64,404,'Convite inválido ou expirado.');$i=DB::table('legal_partner_invitations')->where('token_hash',hash('sha256',$token))->whereNull('used_at')->whereNull('revoked_at')->where('expires_at','>',now())->first();abort_unless($i,404,'Convite inválido ou expirado.');return response()->json(['valid'=>true,'email'=>$i->email,'office_name'=>$i->office_name])->header('Cache-Control','no-store');}
 public function apply(Request $r,LegalPartnerService $s){
  $d=$r->validate(['invitation_token'=>['required','string','size:64'],'office_name'=>['required','string','max:180'],'document'=>['required','string','max:40'],'contact_name'=>['required','string','max:160'],'oab'=>['required','string','max:80'],'email'=>['required','email','max:255'],'phone'=>['required','string','max:40'],'city'=>['required','string','max:100'],'state'=>['required','regex:/^[A-Z]{2}$/'],'service_regions'=>['required','string','max:1000'],'specialties'=>['required','string','max:1000'],'notes'=>['nullable','string','max:2000'],'consent'=>['required','accepted']]);
  $partner=DB::transaction(function()use($r,$s,$d){$i=DB::table('legal_partner_invitations')->where('token_hash',hash('sha256',$d['invitation_token']))->lockForUpdate()->first();abort_unless($i && !$i->used_at && !$i->revoked_at && now()->lessThan($i->expires_at),422,'Convite inválido ou expirado.');$email=mb_strtolower(trim($d['email']));abort_unless($email===$i->email,422,'Use o e-mail que recebeu o convite.');abort_if(LegalPartner::where('email',$email)->exists(),422,'Cadastro já recebido. Aguarde análise administrativa.');unset($d['invitation_token'],$d['consent']);$p=LegalPartner::create([...$d,'email'=>$email,'status'=>'pending_review','consented_at'=>now(),'consent_version'=>'legal-network-20261118']);DB::table('legal_partner_invitations')->where('id',$i->id)->update(['used_at'=>now(),'legal_partner_id'=>$p->id,'updated_at'=>now()]);$s->audit($r,'legal.application_received',$p->id,null,['invitation_id'=>$i->id]);return $p;});
  return response()->json(['message'=>'Cadastro recebido. O acesso depende da análise e liberação pelo admin.','status'=>'pending_review'],201);
 }
 public function partners(){return LegalPartner::with('plan:id,name,monthly_price,audience,active')->latest()->limit(200)->get()->map(fn($p)=>[...$p->makeVisible(['notes','payment_reference'])->toArray(),'access_active'=>$p->hasAccess()]);}
 public function updateProfile(Request $r,LegalPartner $partner,LegalPartnerService $s){
  $d=$r->validate(['office_name'=>['required','string','max:180'],'document'=>['required','string','max:40'],'contact_name'=>['required','string','max:160'],'oab'=>['required','string','max:80'],'phone'=>['required','string','max:40'],'city'=>['required','string','max:100'],'state'=>['required','regex:/^[A-Z]{2}$/'],'service_regions'=>['required','string','max:1000'],'specialties'=>['required','string','max:1000'],'notes'=>['nullable','string','max:2000'],'reason'=>['required','string','min:5','max:500']]);
  DB::transaction(function()use($r,$partner,$s,$d){$p=LegalPartner::whereKey($partner->id)->lockForUpdate()->firstOrFail();$reason=$d['reason'];unset($d['reason']);$before=$p->only(array_keys($d));$p->update($d);$s->audit($r,'legal.profile_updated',$p->id,null,['before'=>$before,'after'=>$d,'reason'=>$reason]);});return response()->json(['message'=>'Cadastro atualizado. E-mail de acesso, plano e liberação foram preservados.']);
 }
 public function activate(Request $r,LegalPartner $partner,LegalPartnerService $s){
  $d=$r->validate(['plan_id'=>['required','integer','exists:plans,id'],'access_until'=>['required','date','after:now'],'activation_method'=>['required',Rule::in(['payment_confirmed','manual'])],'payment_reviewed'=>['accepted_if:activation_method,payment_confirmed'],'payment_reference'=>['nullable','required_if:activation_method,payment_confirmed','string','max:255'],'reason'=>['required','string','min:5','max:500']]);
  DB::transaction(function()use($r,$partner,$s,$d){$p=LegalPartner::whereKey($partner->id)->lockForUpdate()->firstOrFail();$plan=Plan::whereKey($d['plan_id'])->where('audience','legal_partner')->where('active',true)->first();abort_unless($plan,422,'Selecione um plano jurídico ativo.');$before=['status'=>$p->status,'plan_id'=>$p->plan_id,'access_until'=>$p->access_until?->toIso8601String()];$p->update(['status'=>'active','plan_id'=>$plan->id,'plan_snapshot'=>$plan->only(['id','name','monthly_price','complimentary']),'access_until'=>$d['access_until'],'activation_method'=>$d['activation_method'],'payment_reference'=>$d['activation_method']==='payment_confirmed'?$d['payment_reference']:null,'payment_confirmed_at'=>$d['activation_method']==='payment_confirmed'?now():null,'activated_at'=>now()]);$s->audit($r,'legal.access_activated',$p->id,null,['before'=>$before,'plan_id'=>$plan->id,'method'=>$d['activation_method'],'payment_reference'=>$d['activation_method']==='payment_confirmed'?$d['payment_reference']:null,'plan_snapshot'=>$plan->only(['id','name','monthly_price','complimentary']),'access_until'=>$d['access_until'],'reason'=>$d['reason']]);});
  $sent=$s->email($partner->email,'Acesso liberado · Rede Jurídica',"<p>Seu escritório teve o acesso liberado pela administração.</p><p><a href='".LegalPartnerService::PORTAL."'>Entrar no painel jurídico</a></p><p>Use o e-mail cadastrado para receber seu código de acesso.</p>");return response()->json(['message'=>'Acesso liberado.','delivery_status'=>$sent?'sent':'failed','partner'=>$partner->fresh()]);
 }
 public function status(Request $r,LegalPartner $partner,LegalPartnerService $s){$d=$r->validate(['status'=>['required',Rule::in(['suspended','blocked','rejected'])],'reason'=>['required','string','min:5','max:500']]);DB::transaction(function()use($r,$partner,$s,$d){$p=LegalPartner::whereKey($partner->id)->lockForUpdate()->firstOrFail();$p->update(['status'=>$d['status']]);$p->tokens()->delete();DB::table('legal_login_challenges')->where('legal_partner_id',$p->id)->delete();$s->audit($r,'legal.access_revoked',$p->id,null,$d);});return response()->json(['message'=>'Acesso bloqueado; histórico preservado.']);}
 public function requests(){return DB::table('installment_delinquency_actions as a')->join('deals as d','d.id','=','a.deal_id')->join('users as u','u.id','=','a.actor_id')->leftJoin('legal_referrals as r','r.delinquency_action_id','=','a.id')->leftJoin('legal_partners as p','p.id','=','r.legal_partner_id')->where('a.type','legal_support_requested')->orderByDesc('a.id')->limit(200)->get(['a.id','a.deal_id','a.installment_id','a.status','a.payload','a.created_at','d.public_id','d.title','u.name as requester_name','r.id as referral_id','r.status as attendance_status','r.legal_partner_id','r.revoked_at','p.office_name']);}
 public function assign(Request $r,int $action,LegalPartnerService $s){$d=$r->validate(['legal_partner_id'=>['required','integer','exists:legal_partners,id'],'reason'=>['required','string','min:5','max:500']]);
  $id=DB::transaction(function()use($r,$action,$s,$d){$a=DB::table('installment_delinquency_actions')->where('id',$action)->lockForUpdate()->first();abort_unless($a && $a->type==='legal_support_requested' && in_array($a->status,['pending','in_review'],true) && !empty(json_decode($a->payload??'{}',true)['consented_at']),422,'Solicitação não disponível ou sem autorização.');$p=LegalPartner::whereKey($d['legal_partner_id'])->lockForUpdate()->firstOrFail();abort_unless($p->hasAccess(),422,'O escritório precisa estar ativo, com plano e vigência válidos.');$old=DB::table('legal_referrals')->where('delinquency_action_id',$action)->first();abort_if($old?->revoked_at,422,'O compartilhamento deste pedido foi revogado.');$values=['legal_partner_id'=>$p->id,'assigned_by'=>$r->user()->id,'status'=>'received','assigned_at'=>now(),'updated_at'=>now()];if($old){DB::table('legal_referrals')->where('id',$old->id)->update($values);$id=$old->id;}else{$id=DB::table('legal_referrals')->insertGetId([...$values,'delinquency_action_id'=>$action,'created_at'=>now()]);}DB::table('installment_delinquency_actions')->where('id',$action)->update(['status'=>'in_review','updated_at'=>now()]);$s->audit($r,'legal.case_assigned',$p->id,$id,['previous_partner_id'=>$old?->legal_partner_id,'reason'=>$d['reason']]);return $id;});
  $p=LegalPartner::findOrFail($d['legal_partner_id']);$sent=$s->email($p->email,'Nova solicitação · Rede Jurídica',"<p>Há uma nova solicitação encaminhada ao seu escritório.</p><p><a href='".LegalPartnerService::PORTAL."'>Consultar no painel jurídico</a></p>");return response()->json(['message'=>'Solicitação encaminhada.','referral_id'=>$id,'delivery_status'=>$sent?'sent':'failed']);
 }
}
